<form method="POST" action="{{ $staff->exists?route('staff.update',$staff):route('staff.store') }}">@csrf @if($staff->exists)@method('PUT')@endif<h2>{{ $staff->exists?'Edit staff':'Add staff' }}</h2><div class="form-grid"><label>Full name<input name="full_name" value="{{ $staff->full_name }}" required></label><label>Linked login<select name="user_id"><option value="">None</option>@foreach($users as $u)<option value="{{ $u->id }}" {{ $staff->user_id===$u->id?'selected':'' }}>{{ $u->name }}</option>@endforeach</select></label><label>Phone<input name="phone" value="{{ $staff->phone }}"></label><label>Email<input name="email" value="{{ $staff->email }}"></label><label>Specialty<input name="specialty" value="{{ $staff->specialty }}"></label><label>Commission %<input type="number" step="0.01" name="commission_percent" value="{{ $staff->commission_percent ?: 0 }}"></label><label class="span-2">Assigned services<select name="services[]" multiple size="5">@foreach($services as $sv)<option value="{{ $sv->id }}" {{ $staff->exists&&$staff->services->contains($sv->id)?'selected':'' }}>{{ $sv->name }}</option>@endforeach</select></label><label class="span-2">Notes<textarea name="notes">{{ $staff->notes }}</textarea></label><label class="check span-2"><input type="hidden" name="active" value="0"><input type="checkbox" name="active" value="1" {{ !$staff->exists||$staff->active?'checked':'' }}> Active staff member</label></div><button class="btn btn-primary btn-full">Save staff</button></form>
